const phase={version:1,code:'cooling',day:'2026-10-21',B_t:4,L_floor:2,U_opt:6,P_3d:12,today_installs_utc:3,floor_met:true,remaining_installs:0,trend_percent:-30,completed_temperature:-100,stabilization_days_remaining:4,peak_window_days_remaining:0,countdown_conditional:true};
