function marketFixture(size,params,multiOwn){
 const all=Array.from({length:size-1},(_,i)=>project(100+i));all.splice(2,0,project(42));
 all.forEach((p,i)=>{p.rank=i+1;p.out_of=size;p.top_percent=Math.round(100*(i+1)/size*10)/10;p.own=p.app_id===42;const target=Math.max(0,465-i*18);p.scoring.factors.forEach((f,j)=>{f.score=i<=2?(j===0?100-15*i:f.score):Math.round(f.score*target/429*100)/100;});p.scoring.market_score=Math.floor(p.scoring.factors.reduce((sum,f)=>sum+f.score*f.normalized_weight,0)*10*.6+.5);});
 const bins=Array(20).fill(0),tiers=Array(5).fill(0),seen=Array(5).fill(0);
 all.forEach(p=>{p.bin_index=Math.min(19,Math.floor(p.scoring.market_score/50));p.scoring.tier=5-Math.floor(p.bin_index/4);bins[p.bin_index]++;tiers[5-p.scoring.tier]++;p.tier_rank=++seen[5-p.scoring.tier];p.points_to_next_tier=p.scoring.tier>1?(6-p.scoring.tier)*200-p.scoring.market_score:null;if(multiOwn&&p.app_id===110)p.own=true;});
 all.forEach((p,i)=>{p.tier_total=tiers[5-p.scoring.tier];Object.assign(p,{next_rank_score:i?all[i-1].scoring.market_score:null,points_to_next_rank:i?all[i-1].scoring.market_score-p.scoring.market_score:null,points_to_overtake:i?all[i-1].scoring.market_score-p.scoring.market_score+(p.app_id>all[i-1].app_id?1:0):null,prev_rank_score:all[i+1]?.scoring.market_score??null,lead_over_prev_rank:all[i+1]?p.scoring.market_score-all[i+1].scoring.market_score:null});});
 const own=all.filter(p=>p.own).map(clone),competition={version:2,bin_width:50,bins,tier_counts:tiers,total:size,unscored:0};
 const match=o=>(!params.get('source')||o.source===params.get('source'))&&(!params.get('country')||!o.country||o.country===params.get('country'))&&(!params.get('duration')||(params.get('duration')==='28+'?o.duration_days>=28:o.duration_days===Number(params.get('duration'))))&&(params.get('instant_only')!=='true'||o.instant_install)&&(params.get('contracts_only')!=='true'||o.offer_type==='contract'&&o.ready)&&(params.get('reviews_only')!=='true'||o.reviews_available);
 const active=['source','country','duration','instant_only','contracts_only','reviews_only'].some(k=>params.has(k));
 const filtered=all.map(p=>({...p,offers:p.offers.filter(match)})).filter(p=>(!active||p.offers.length)&&(!params.get('tier')||p.scoring.tier===Number(params.get('tier')))),ranking=filtered,queue=filtered.filter(p=>!p.own),offset=Number(params.get('offset')||0),tab=params.get('tab');
 return {status:'success',is_simulation:true,country:'TH',ranking_scope:'eligible_projects',queue:tab==='ranking'?[]:queue.slice(offset,offset+30),ranking:tab==='queue'?[]:ranking.slice(offset,offset+30),radar:own,competition,phase1_sandbox:{phase1_active_total:40,phase1_graduating_soon:13,own_projects:[{app_id:7,name:'Closed Test Extra Days',day:28,public:true}]},queue_capabilities:{instant_install:true,request_queue:true},offset,limit:30,totals:{queue:queue.length,ranking:ranking.length}};
}

module.exports={phase,clone,score,project,marketFixture};
